import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"Public contracts","description":"","frontmatter":{},"headers":[],"relativePath":"contracts.md","filePath":"contracts.md","lastUpdated":1786757719000}`),a={name:`contracts.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="public-contracts" tabindex="-1">Public contracts <a class="header-anchor" href="#public-contracts" aria-label="Permalink to “Public contracts”">​</a></h1><p>The stable public boundary is recorded in <a href="https://github.com/fontmin-rs/fontmin-rs/blob/main/contracts/public-api.json" target="_blank" rel="noreferrer"><code>contracts/public-api.json</code></a>. CI compares the implementation with that machine-readable inventory. Changing the inventory is an intentional compatibility decision: update the changelog, migration guidance, and affected tests in the same pull request.</p><p>The environments and runtime boundaries reconfirmed for <code>1.0</code> are recorded in <a href="https://github.com/fontmin-rs/fontmin-rs/blob/main/contracts/support.json" target="_blank" rel="noreferrer"><code>contracts/support.json</code></a>. CI checks that inventory against package engines, Cargo metadata, toolchains, native build targets, and browser matrices.</p><h2 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to “CLI”">​</a></h2><p>The commands <code>build</code>, <code>subset</code>, <code>coverage</code>, <code>inspect</code>, <code>convert</code>, <code>bench</code>, <code>init</code>, and <code>doctor</code> are frozen together with the long flags listed in the contract. Successful commands exit with <code>0</code>; argument, configuration, I/O, and processing failures exit with <code>1</code>. Scripts should additionally branch on a stable diagnostic code when one is available.</p><p>Help presentation, whitespace, terminal colors, and human-readable wording are not frozen. The command names, accepted flags, exit status, and diagnostic codes are.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>The Rust CLI, Node package, and browser WASM package have deliberately different boundaries:</p><ul><li>Rust accepts project fields, serializable built-in plugin descriptors, and the six documented config-file extensions.</li><li>Node accepts filesystem or in-memory inputs, custom plugin hooks, and <code>runtime: &quot;native&quot; | &quot;wasm&quot; | &quot;auto&quot;</code>.</li><li>Browser WASM accepts only in-memory <code>assets</code> and <code>plugins</code>.</li></ul><p>The exact top-level fields are in the contract inventory. Option behavior and nested fields remain documented in <a href="./guide/config">Configuration</a>.</p><h2 id="javascript-exports-and-plugin-lifecycle" tabindex="-1">JavaScript exports and plugin lifecycle <a class="header-anchor" href="#javascript-exports-and-plugin-lifecycle" aria-label="Permalink to “JavaScript exports and plugin lifecycle”">​</a></h2><p>The runtime export names for <code>fontmin-rs</code>, its <code>./plugins</code>, <code>./presets</code>, and <code>./compat</code> subpaths, and <code>@fontmin-rs/wasm</code> are frozen. Type-only exports follow the same compatibility policy, with TypeScript compilation tests acting as the gate.</p><p>Node plugins run <code>buildStart</code>, <code>transform</code>, <code>generateBundle</code>, and <code>buildEnd</code> in that order. A breaking hook signature or ordering change follows the deprecation policy and requires explicit release planning.</p><h2 id="diagnostics-and-file-names" tabindex="-1">Diagnostics and file names <a class="header-anchor" href="#diagnostics-and-file-names" aria-label="Permalink to “Diagnostics and file names”">​</a></h2><p>Stable Rust-originated diagnostics use the <code>fontmin::*</code> codes listed in the inventory, including <code>fontmin::invalid_font</code>. Node and WASM expose those codes through <code>FontminDiagnosticError</code>.</p><p>Generated files follow these templates:</p><table tabindex="0"><thead><tr><th>Output</th><th>Template</th></tr></thead><tbody><tr><td>Normal transform</td><td><code>{stem}.{extension}</code></td></tr><tr><td>Named Unicode delivery slice</td><td><code>{stem}-{slice}.{extension}</code></td></tr><tr><td>Default SVG icon-font stem</td><td><code>iconfont</code></td></tr><tr><td>Preserved original input asset</td><td><code>{input-file-name}</code></td></tr></tbody></table><p>Explicit <code>fileName</code>, <code>ext</code>, or icon-font <code>fontName</code> options override the corresponding default. Tests freeze representative output sets and CSS URLs, not encoder byte identity.</p><h2 id="compatibility-rule" tabindex="-1">Compatibility rule <a class="header-anchor" href="#compatibility-rule" aria-label="Permalink to “Compatibility rule”">​</a></h2><p>Additive changes still require an inventory update and a successful full release gate. Removing or changing an item follows the <a href="./deprecation">deprecation policy</a>. The <code>1.0.0</code> contract uses a separately versioned release-candidate cycle plus <a href="./compatibility">standalone compatibility evidence</a>; both gates passed before stable promotion.</p>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};